"use client";

import { useAuth } from "@/context/AuthContext";
import { useCart } from "@/context/CartContext";
import { fixVietnameseText, formatVND, productImageUrl } from "@/lib/utils";
import type { Product } from "@/types/product";
import { LogOut, Menu, Search, ShoppingBag, User as UserIcon, X } from "lucide-react";
import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import type React from "react";
import { useCallback, useEffect, useMemo, useState } from "react";

export default function Header() {
  const { cart } = useCart();
  const { user, logout } = useAuth();
  const cartCount = cart?.reduce((total, item) => total + item.quantity, 0) || 0;
  const [isMobileOpen, setIsMobileOpen] = useState(false);
  const [isScrolled, setIsScrolled] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [products, setProducts] = useState<Product[]>([]);
  const pathname = usePathname();
  const router = useRouter();

  const normalizedQuery = searchQuery.trim().toLowerCase();
  const categorySuggestions = useMemo(() => {
    if (!normalizedQuery) return [];
    const categories = Array.from(new Set(products.map((product) => fixVietnameseText(product.category)).filter(Boolean))) as string[];
    return categories.filter((category) => category.toLowerCase().includes(normalizedQuery)).slice(0, 3);
  }, [normalizedQuery, products]);

  const productSuggestions = useMemo(() => {
    if (!normalizedQuery) return [];
    return products.filter((product) => product.name.toLowerCase().includes(normalizedQuery) || fixVietnameseText(product.description).toLowerCase().includes(normalizedQuery)).slice(0, 4);
  }, [normalizedQuery, products]);

  const hasSearchSuggestions = normalizedQuery.length > 0 && (categorySuggestions.length > 0 || productSuggestions.length > 0);

  const handleSearch = (event: React.FormEvent) => {
    event.preventDefault();
    if (searchQuery.trim()) {
      router.push(`/search?q=${encodeURIComponent(searchQuery.trim())}`);
      setIsSearchOpen(false);
      setIsMobileOpen(false);
    }
  };

  useEffect(() => {
    const handleScroll = () => setIsScrolled(window.scrollY > 10);
    handleScroll();
    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  useEffect(() => {
    fetch("/api/products")
      .then(async (response) => (response.ok ? response.json() : []))
      .then((items: Product[]) => setProducts(items))
      .catch(() => setProducts([]));
  }, []);

  useEffect(() => setIsMobileOpen(false), [pathname]);

  const toggleMobileMenu = useCallback(() => setIsMobileOpen((prev) => !prev), []);
  const closeMobileMenu = useCallback(() => setIsMobileOpen(false), []);
  const isActivePath = (path: string) => pathname === path;

  const navItems = [
    { href: "/category/nuoc-hoa-nu", label: "Nước hoa nữ" },
    { href: "/category/nuoc-hoa-nam", label: "Nước hoa nam" },
    { href: "/category/unisex", label: "Unisex" },
    { href: "/contact", label: "Liên hệ" },
  ];

  return (
    <header className={`sticky top-0 z-50 border-b transition-all duration-300 ${isScrolled ? "border-[#d6bd7a]/25 bg-[#070607]/94 shadow-[0_18px_55px_rgba(0,0,0,0.42)] backdrop-blur-xl" : "border-[#d6bd7a]/12 bg-[#070607]/82 backdrop-blur-md"}`}>
      <div className="mx-auto max-w-[1500px] px-4 py-3 sm:px-6 lg:px-8">
        <div className="flex items-center gap-4">
          <Link className="shrink-0 font-serif text-2xl tracking-[0.02em] text-[#f7efe1] transition hover:text-[#d6bd7a]" href="/" aria-label="VANHPERFUME Home">
            VANH<span className="italic text-[#d6bd7a]">PERFUME</span>
          </Link>

          <nav className="hidden items-center gap-1 md:flex" role="navigation" aria-label="Main navigation">
            {navItems.map(({ href, label }) => (
              <Link key={href} href={href} className={`px-3 py-2 text-sm font-medium transition ${isActivePath(href) ? "text-[#d6bd7a]" : "text-[#cfc4ad] hover:text-[#f7efe1]"}`} aria-current={isActivePath(href) ? "page" : undefined}>
                {label}
              </Link>
            ))}
          </nav>

          <div className="hidden min-w-[330px] flex-1 lg:flex xl:min-w-[460px]">
            <form className="relative ml-auto w-full max-w-xl" onSubmit={handleSearch}>
              <input type="search" placeholder="Tìm kiếm mùi hương, nhóm hương..." value={searchQuery} onChange={(event) => setSearchQuery(event.target.value)} className="h-11 w-full border border-[#d6bd7a]/25 bg-black/28 pl-11 pr-4 text-sm text-[#f7efe1] outline-none transition placeholder:text-[#cfc4ad]/48 focus:border-[#d6bd7a]/65 focus:bg-black/45" aria-label="Tìm kiếm sản phẩm" />
              <Search className="absolute left-4 top-1/2 h-4 w-4 -translate-y-1/2 text-[#d6bd7a]" />
              {hasSearchSuggestions && <SearchSuggestions categorySuggestions={categorySuggestions} productSuggestions={productSuggestions} onClose={() => { setSearchQuery(""); setIsSearchOpen(false); setIsMobileOpen(false); }} />}
            </form>
          </div>

          <div className="ml-auto flex items-center gap-2">
            <button onClick={() => setIsSearchOpen(!isSearchOpen)} className="grid h-10 w-10 place-items-center border border-[#d6bd7a]/20 text-[#f7efe1] transition hover:border-[#d6bd7a]/55 hover:text-[#d6bd7a] lg:hidden" aria-label="Search">
              <Search className="h-5 w-5" />
            </button>
            <button onClick={toggleMobileMenu} className="grid h-10 w-10 place-items-center border border-[#d6bd7a]/20 text-[#f7efe1] transition hover:border-[#d6bd7a]/55 hover:text-[#d6bd7a] md:hidden" aria-label="Toggle navigation menu" aria-expanded={isMobileOpen}>
              {isMobileOpen ? <X className="h-5 w-5" /> : <Menu className="h-5 w-5" />}
            </button>
            <Link href="/cart" className="relative grid h-10 w-10 place-items-center border border-[#d6bd7a]/20 text-[#f7efe1] transition hover:border-[#d6bd7a]/55 hover:text-[#d6bd7a]" aria-label={`Shopping cart with ${cartCount} items`}>
              <ShoppingBag className="h-5 w-5" />
              {cartCount > 0 && <span className="absolute -right-2 -top-2 grid h-5 min-w-5 place-items-center bg-[#d6bd7a] px-1 text-xs font-bold text-black">{cartCount > 99 ? "99+" : cartCount}</span>}
            </Link>

            <div className="hidden items-center gap-2 sm:flex">
              {user ? (
                <div className="flex items-center gap-3 border border-[#d6bd7a]/20 bg-black/30 px-3 py-1.5">
                  <Link href="/profile" className="flex items-center gap-2 text-[#f7efe1] transition hover:text-[#d6bd7a]">
                    {user.avatar ? <img src={user.avatar} alt="Avatar" className="h-6 w-6 rounded-full bg-background" /> : <span className="grid h-6 w-6 place-items-center bg-[#d6bd7a]/18"><UserIcon className="h-3 w-3 text-[#d6bd7a]" /></span>}
                    <span className="text-sm font-medium">{user.name}</span>
                  </Link>
                  <button onClick={logout} className="text-[#cfc4ad] transition hover:text-[#d6bd7a]" title="Đăng xuất"><LogOut className="h-4 w-4" /></button>
                </div>
              ) : (
                <Link href="/login" className="border border-[#d6bd7a]/35 px-5 py-2.5 text-sm font-semibold uppercase tracking-[0.14em] text-[#f7efe1] transition hover:bg-[#d6bd7a] hover:text-black">
                  Đăng nhập
                </Link>
              )}
            </div>
          </div>
        </div>

        {isSearchOpen && (
          <div className="mt-4 lg:hidden">
            <form className="relative" onSubmit={handleSearch}>
              <input type="search" placeholder="Tìm kiếm mùi hương..." value={searchQuery} onChange={(event) => setSearchQuery(event.target.value)} className="h-12 w-full border border-[#d6bd7a]/25 bg-black/35 pl-11 pr-4 text-sm text-[#f7efe1] outline-none placeholder:text-[#cfc4ad]/48 focus:border-[#d6bd7a]/65" aria-label="Tìm kiếm sản phẩm" autoFocus />
              <Search className="absolute left-4 top-1/2 h-4 w-4 -translate-y-1/2 text-[#d6bd7a]" />
              {hasSearchSuggestions && <SearchSuggestions categorySuggestions={categorySuggestions} productSuggestions={productSuggestions} onClose={() => { setSearchQuery(""); setIsSearchOpen(false); setIsMobileOpen(false); }} />}
            </form>
          </div>
        )}

        {isMobileOpen && (
          <nav className="mt-4 border-t border-[#d6bd7a]/15 pt-4 md:hidden" role="navigation" aria-label="Mobile navigation">
            <div className="flex flex-col gap-2">
              {navItems.map(({ href, label }) => (
                <Link key={href} href={href} onClick={closeMobileMenu} className={`px-3 py-3 text-sm font-medium transition ${isActivePath(href) ? "bg-[#d6bd7a]/12 text-[#d6bd7a]" : "text-[#cfc4ad] hover:bg-[#d6bd7a]/10 hover:text-[#f7efe1]"}`} aria-current={isActivePath(href) ? "page" : undefined}>{label}</Link>
              ))}
              {!user && <Link href="/login" onClick={closeMobileMenu} className="mt-2 border border-[#d6bd7a]/35 px-3 py-3 text-center text-sm font-semibold uppercase tracking-[0.14em] text-[#f7efe1]">Đăng nhập</Link>}
            </div>
          </nav>
        )}
      </div>
    </header>
  );
}

function SearchSuggestions({ categorySuggestions, productSuggestions, onClose }: { categorySuggestions: string[]; productSuggestions: Product[]; onClose: () => void }) {
  return (
    <div className="absolute left-0 right-0 top-full z-50 mt-2 border border-[#d6bd7a]/25 bg-[#0b0908] shadow-[0_24px_80px_rgba(0,0,0,0.45)]">
      <div className="space-y-4 p-4">
        {categorySuggestions.length > 0 && (
          <div>
            <div className="mb-3 text-xs uppercase tracking-[0.24em] text-[#d6bd7a]">Gợi ý danh mục</div>
            <div className="grid gap-2 sm:grid-cols-2">{categorySuggestions.map((category) => <Link key={category} href={`/search?q=${encodeURIComponent(category)}`} onClick={onClose} className="block border border-[#d6bd7a]/18 px-4 py-3 text-sm text-[#f7efe1] transition hover:border-[#d6bd7a]/45">{category}</Link>)}</div>
          </div>
        )}
        {productSuggestions.length > 0 && (
          <div>
            <div className="mb-3 text-xs uppercase tracking-[0.24em] text-[#d6bd7a]">Sản phẩm gợi ý</div>
            <div className="space-y-2">{productSuggestions.map((product) => <SearchProductSuggestion key={product.id} product={product} onClick={onClose} />)}</div>
          </div>
        )}
      </div>
    </div>
  );
}

function SearchProductSuggestion({ product, onClick }: { product: Product; onClick: () => void }) {
  const category = fixVietnameseText(product.category);

  return (
    <Link href={`/product/${product.id}`} onClick={onClick} className="flex items-center gap-3 border border-[#d6bd7a]/18 px-3 py-3 transition hover:border-[#d6bd7a]/45">
      <img src={productImageUrl(product.image)} alt={product.name} className="h-14 w-14 shrink-0 border border-[#d6bd7a]/18 bg-[#efe7d6] object-cover" />
      <div className="min-w-0 flex-1">
        <p className="line-clamp-1 text-sm font-semibold text-[#f7efe1]">{product.name}</p>
        <p className="mt-1 line-clamp-1 text-xs text-[#cfc4ad]/70">{category || "Sản phẩm"}</p>
      </div>
      <span className="shrink-0 text-sm font-semibold text-[#d6bd7a]">{formatVND(product.price)}</span>
    </Link>
  );
}
